1	#!/usr/bin/env node
2	// SVG-vs-PNG acceptance harness — a developer tool, not a CI gate.
3	//
4	// Builds the retired PNG renderer (from a worktree pinned to the last commit
5	// before PNG support was removed) and the current SVG-only renderer, exports
6	// the same themes from both against the same deterministic --data fixture,
7	// rasterizes each SVG headlessly in the *same font* the PNG renderer used
8	// (Hack Nerd Font) at a matched scale, diffs the raster against the
9	// reference PNG with pixelmatch, and writes an index.html contact sheet so a
10	// human can eyeball whether they still read as the same prompt.
11	//
12	// Usage (run from this directory, after `npm install` once):
13	//
14	//   node compare.mjs                          six default themes
15	//   node compare.mjs cobalt2 atomic            only the named themes
16	//   node compare.mjs --all                     every theme in ../../themes
17	//   node compare.mjs --skip-build               reuse bin/*.exe from a prior run
18	//   node compare.mjs --png-worktree <path>      override the old renderer's worktree
19	//
20	// Output lands in ./out/: <theme>.png (reference), <theme>.svg (exported),
21	// <theme>.raster.png (headless SVG raster), <theme>.diff.png, and
22	// index.html.
23	import { spawnSync } from "node:child_process";
24	import fs from "node:fs";
25	import path from "node:path";
26	import { fileURLToPath } from "node:url";
27	
28	import { PNG } from "pngjs";
29	import pixelmatch from "pixelmatch";
30	import { chromium } from "playwright";
31	
32	import { extractZipEntry } from "./zip.mjs";
33	
34	const __dirname = path.dirname(fileURLToPath(import.meta.url));
35	const REPO_ROOT = path.resolve(__dirname, "..", "..");
36	const THEMES_DIR = path.join(REPO_ROOT, "themes");
37	const DATA_FIXTURE = path.join(REPO_ROOT, "src", "prompt", "testdata", "fixtures", "prompt.data.json");
38	
39	const BIN_DIR = path.join(__dirname, "bin");
40	const FONT_DIR = path.join(__dirname, "fonts");
41	const OUT_DIR = path.join(__dirname, "out");
42	const FONT_PATH = path.join(FONT_DIR, "HackNerdFont-Regular.ttf");
43	const FONT_FAMILY = "Hack Nerd Font";
44	
45	const EXE = process.platform === "win32" ? ".exe" : "";
46	const OLD_BIN = path.join(BIN_DIR, `omp-png${EXE}`);
47	const NEW_BIN = path.join(BIN_DIR, `omp-svg${EXE}`);
48	
49	const DEFAULT_THEMES = [
50	  "M365Princess",
51	  "clean-detailed",
52	  "cloud-native-azure",
53	  "cobalt2",
54	  "jandedobbeleer",
55	  "atomic",
56	];
57	
58	// The PNG renderer's reference em size was 48px (see src/svg/window.go's
59	// newWindowGeometry doc comment); the SVG exporter has no --font-size flag
60	// and always renders at a 16px em (src/svg/svg.go's defaultFontSize). 48/16
61	// = 3, so rasterizing the SVG's own natural geometry at 3x device scale
62	// reproduces the PNG's reference resolution exactly, without needing a flag
63	// that doesn't exist. Every window-chrome constant in svg/window.go is
64	// already derived as `constant * (FontSize / 48)`, so this 3x upscale is
65	// mathematically the same shape the SVG package would produce if it *could*
66	// be asked for FontSize 48 directly.
67	const DEVICE_SCALE_FACTOR = 3;
68	
69	// pixelmatch match sensitivity. 0.1 is pixelmatch's own documented default
70	// and already tolerant of the antialiasing/subpixel noise a font rasterizer
71	// introduces; see parseArgs' --threshold for overriding it.
72	const DEFAULT_THRESHOLD = 0.1;
73	
74	function parseArgs(argv) {
75	  const opts = {
76	    themes: null,
77	    all: false,
78	    skipBuild: false,
79	    pngWorktree: process.env.OMP_PNG_WORKTREE || path.join(os_tmpdir(), "omp-png"),
80	    threshold: DEFAULT_THRESHOLD,
81	  };
82	
83	  const positional = [];
84	
85	  for (let i = 0; i < argv.length; i++) {
86	    const arg = argv[i];
87	
88	    switch (arg) {
89	      case "--all":
90	        opts.all = true;
91	        break;
92	      case "--skip-build":
93	        opts.skipBuild = true;
94	        break;
95	      case "--png-worktree":
96	        opts.pngWorktree = argv[++i];
97	        break;
98	      case "--threshold":
99	        opts.threshold = Number.parseFloat(argv[++i]);
100	        break;
101	      default:
102	        if (arg.startsWith("--")) {
103	          throw new Error(`unknown flag: ${arg}`);
104	        }
105	
106	        positional.push(arg);
107	    }
108	  }
109	
110	  if (positional.length > 0) {
111	    opts.themes = positional;
112	  }
113	
114	  return opts;
115	}
116	
117	function os_tmpdir() {
118	  return process.env.TEMP || process.env.TMP || "/tmp";
119	}
120	
121	function resolveThemeList(opts) {
122	  if (opts.all) {
123	    return fs
124	      .readdirSync(THEMES_DIR)
125	      .filter((f) => f.endsWith(".omp.json"))
126	      .map((f) => f.slice(0, -".omp.json".length))
127	      .sort();
128	  }
129	
130	  return opts.themes ?? DEFAULT_THEMES;
131	}
