433	    </section>`,
434	    )
435	    .join("\n");
436	
437	  const html = `<!doctype html>
438	<html>
439	<head>
440	<meta charset="utf-8">
441	<title>SVG vs PNG acceptance harness</title>
442	<style>
443	  :root { color-scheme: dark; }
444	  body {
445	    background: #14161a;
446	    color: #e6e9ef;
447	    font: 14px/1.5 system-ui, sans-serif;
448	    padding: 24px;
449	    margin: 0;
450	  }
451	  h1 { font-size: 18px; margin: 0 0 6px; }
452	  p.intro { color: #8b98a9; margin: 0 0 28px; max-width: 72ch; }
453	  h2 { font-size: 16px; margin: 0 0 4px; color: #9fd0ff; }
454	  .stats { font-size: 12px; color: #8b98a9; margin: 0 0 10px; }
455	  .row { display: flex; gap: 14px; flex-wrap: wrap; align-items: flex-start; }
456	  figure { margin: 0; }
457	  figcaption {
458	    font-size: 11px;
459	    text-transform: uppercase;
460	    letter-spacing: .06em;
461	    color: #8b98a9;
462	    margin: 0 0 4px;
463	  }
