#!/usr/bin/env node
// SVG-vs-PNG acceptance harness — a developer tool, not a CI gate.
//
// Builds the retired PNG renderer (from a worktree pinned to the last commit
// before PNG support was removed) and the current SVG-only renderer, exports
// the same themes from both against the same deterministic --data fixture,
// rasterizes each SVG headlessly in the *same font* the PNG renderer used
// (Hack Nerd Font) at a matched scale, diffs the raster against the
// reference PNG with pixelmatch, and writes an index.html contact sheet so a
// human can eyeball whether they still read as the same prompt.
//
// Usage (run from this directory, after `npm install` once):
//
//   node compare.mjs                          six default themes
//   node compare.mjs cobalt2 atomic            only the named themes
//   node compare.mjs --all                     every theme in ../../themes
//   node compare.mjs --skip-build               reuse bin/*.exe from a prior run
//   node compare.mjs --png-worktree <path>      override the old renderer's worktree
//
// Output lands in ./out/: <theme>.png (reference), <theme>.svg (exported),
// <theme>.raster.png (headless SVG raster), <theme>.diff.png, and
// index.html.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { PNG } from "pngjs";
import pixelmatch from "pixelmatch";
import { chromium } from "playwright";

import { extractZipEntry } from "./zip.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..", "..");
const THEMES_DIR = path.join(REPO_ROOT, "themes");
const DATA_FIXTURE = path.join(REPO_ROOT, "src", "prompt", "testdata", "fixtures", "prompt.data.json");

const BIN_DIR = path.join(__dirname, "bin");
const FONT_DIR = path.join(__dirname, "fonts");
const OUT_DIR = path.join(__dirname, "out");
const FONT_PATH = path.join(FONT_DIR, "HackNerdFont-Regular.ttf");
const FONT_FAMILY = "Hack Nerd Font";

const EXE = process.platform === "win32" ? ".exe" : "";
const OLD_BIN = path.join(BIN_DIR, `omp-png${EXE}`);
const NEW_BIN = path.join(BIN_DIR, `omp-svg${EXE}`);

const DEFAULT_THEMES = [
  "M365Princess",
  "clean-detailed",
  "cloud-native-azure",
  "cobalt2",
  "jandedobbeleer",
  "atomic",
];

// The PNG renderer's reference em size was 48px (see src/svg/window.go's
// newWindowGeometry doc comment); the SVG exporter has no --font-size flag
// and always renders at a 16px em (src/svg/svg.go's defaultFontSize). 48/16
// = 3, so rasterizing the SVG's own natural geometry at 3x device scale
// reproduces the PNG's reference resolution exactly, without needing a flag
// that doesn't exist. Every window-chrome constant in svg/window.go is
// already derived as `constant * (FontSize / 48)`, so this 3x upscale is
// mathematically the same shape the SVG package would produce if it *could*
// be asked for FontSize 48 directly.
const DEVICE_SCALE_FACTOR = 3;

// pixelmatch match sensitivity. 0.1 is pixelmatch's own documented default
// and already tolerant of the antialiasing/subpixel noise a font rasterizer
// introduces; see parseArgs' --threshold for overriding it.
const DEFAULT_THRESHOLD = 0.1;

function parseArgs(argv) {
  const opts = {
    themes: null,
    all: false,
    skipBuild: false,
    pngWorktree: process.env.OMP_PNG_WORKTREE || path.join(os_tmpdir(), "omp-png"),
    threshold: DEFAULT_THRESHOLD,
  };

  const positional = [];

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    switch (arg) {
      case "--all":
        opts.all = true;
        break;
      case "--skip-build":
        opts.skipBuild = true;
        break;
      case "--png-worktree":
        opts.pngWorktree = argv[++i];
        break;
      case "--threshold":
        opts.threshold = Number.parseFloat(argv[++i]);
        break;
      default:
        if (arg.startsWith("--")) {
          throw new Error(`unknown flag: ${arg}`);
        }

        positional.push(arg);
    }
  }

  if (positional.length > 0) {
    opts.themes = positional;
  }

  return opts;
}

function os_tmpdir() {
  return process.env.TEMP || process.env.TMP || "/tmp";
}

function resolveThemeList(opts) {
  if (opts.all) {
    return fs
      .readdirSync(THEMES_DIR)
      .filter((f) => f.endsWith(".omp.json"))
      .map((f) => f.slice(0, -".omp.json".length))
      .sort();
  }

  return opts.themes ?? DEFAULT_THEMES;
}

function run(cmd, args, cwd) {
  console.log(`+ ${cmd} ${args.join(" ")}${cwd ? `  (in ${cwd})` : ""}`);
  const res = spawnSync(cmd, args, { cwd, stdio: "inherit", shell: false });

  if (res.error) {
    throw res.error;
  }

  if (res.status !== 0) {
    throw new Error(`command failed (exit ${res.status}): ${cmd} ${args.join(" ")}`);
  }
}

function buildBinaries(opts) {
  fs.mkdirSync(BIN_DIR, { recursive: true });

  const oldSrc = path.join(opts.pngWorktree, "src");

  if (!fs.existsSync(oldSrc)) {
    throw new Error(
      `retired PNG renderer worktree not found at ${opts.pngWorktree} (expected a Go module at ${oldSrc}). ` +
        "Pass --png-worktree <path> to point at the worktree checked out at the last commit before PNG " +
        "support was removed.",
    );
  }

  console.log("\nBuilding retired PNG renderer...");
  run("go", ["build", "-o", OLD_BIN, "."], oldSrc);

  console.log("\nBuilding current SVG renderer...");
  run("go", ["build", "-o", NEW_BIN, "."], path.join(REPO_ROOT, "src"));
}

// The PNG renderer downloads and caches Hack.zip itself (see
// cli/image/image.go's loadDefaultFonts); reuse that same cache instead of
// fetching it twice. Falls back to downloading it fresh if no cache is
// found anywhere.
function ensureFont() {
  if (fs.existsSync(FONT_PATH)) {
    return;
  }

  fs.mkdirSync(FONT_DIR, { recursive: true });

  const candidateCaches = [
    process.env.OMP_CACHE_DIR,
    process.platform === "win32" ? path.join(process.env.LOCALAPPDATA ?? "", "oh-my-posh") : null,
    process.env.XDG_CACHE_HOME ? path.join(process.env.XDG_CACHE_HOME, "oh-my-posh") : null,
    path.join(os_home(), ".cache", "oh-my-posh"),
  ].filter(Boolean);

  for (const dir of candidateCaches) {
    const zipPath = path.join(dir, "Hack.zip");

    if (fs.existsSync(zipPath)) {
      console.log(`Extracting HackNerdFont-Regular.ttf from cached ${zipPath}`);
      const zipBuf = fs.readFileSync(zipPath);
      const ttf = extractZipEntry(zipBuf, "HackNerdFont-Regular.ttf");
      fs.writeFileSync(FONT_PATH, ttf);
      return;
    }
  }

  console.log("No cached Hack.zip found; downloading it (same URL the retired PNG renderer used)...");
  downloadAndExtractFont();
}

function os_home() {
  return process.env.USERPROFILE || process.env.HOME || os_tmpdir();
}

async function downloadAndExtractFont() {
  const url = "https://github.com/ryanoasis/nerd-fonts/releases/download/v3.2.1/Hack.zip";
  const res = await fetch(url);

  if (!res.ok) {
    throw new Error(`failed to download ${url}: ${res.status} ${res.statusText}`);
  }

  const zipBuf = Buffer.from(await res.arrayBuffer());
  const ttf = extractZipEntry(zipBuf, "HackNerdFont-Regular.ttf");
  fs.writeFileSync(FONT_PATH, ttf);
}

function readPngDimensions(pngPath) {
  const buf = fs.readFileSync(pngPath);
  // IHDR is the first chunk in a well-formed PNG: 8-byte signature, 4-byte
  // length, 4-byte "IHDR", then width/height as big-endian uint32s.
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

// Renders svgMarkup inside a headless page whose viewport (at
// DEVICE_SCALE_FACTOR) targets targetWidth x targetHeight device pixels —
// the reference PNG's own dimensions — so the SVG's vector content is
// rescaled by the browser itself (crisp) rather than by resampling a raster
// afterwards. The SVG keeps its own viewBox, so content scales
// proportionally to fill the forced box.
async function rasterizeSVG(browser, svgMarkup, fontBase64, targetWidth, targetHeight) {
  const cssWidth = Math.max(1, Math.round(targetWidth / DEVICE_SCALE_FACTOR));
  const cssHeight = Math.max(1, Math.round(targetHeight / DEVICE_SCALE_FACTOR));

  // The exporter's <svg> carries no preserveAspectRatio, so it defaults to
  // "xMidYMid meet": the browser would scale the viewBox uniformly to fit
  // inside the CSS box forced below and letterbox/center it, rather than
  // filling that box — which silently reintroduces a spatial offset between
  // the two rasters (content shifted down/right by the letterboxing gap)
  // that swamped the diff with edge noise before this fix. "none" makes the
  // two axes scale independently, actually filling cssWidth x cssHeight.
  svgMarkup = svgMarkup.replace("<svg ", '<svg preserveAspectRatio="none" ');

  const context = await browser.newContext({
    viewport: { width: cssWidth, height: cssHeight },
    deviceScaleFactor: DEVICE_SCALE_FACTOR,
  });

  const page = await context.newPage();

  const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  @font-face {
    font-family: "${FONT_FAMILY}";
    src: url(data:font/ttf;base64,${fontBase64}) format("truetype");
    font-weight: normal;
    font-style: normal;
  }
  html, body { margin: 0; padding: 0; background: transparent; }
  /* Force the SVG's rendered box to exactly the viewport (which
     DEVICE_SCALE_FACTOR then rasterizes to targetWidth x targetHeight); the
     viewBox the exporter already wrote keeps the content proportional. */
  svg { display: block; width: 100vw; height: 100vh; }
</style>
</head>
<body>${svgMarkup}</body>
</html>`;

  await page.setContent(html, { waitUntil: "networkidle" });
  await page.evaluate(() => document.fonts.ready);
  // One extra frame so the webfont swap (FOUT) has actually repainted
  // before the screenshot — document.fonts.ready resolves once the font is
  // *loaded*, not once the page has repainted with it.
  await page.waitForTimeout(50);

  // omitBackground: true keeps the page's transparent regions transparent
  // in the captured PNG (alpha 0) instead of flattening them onto opaque
  // white. The reference PNG's own canvas outside the window+shadow is
  // genuinely transparent (image.go's gg context starts fully transparent
  // and is never filled) — matching that, rather than defaulting to white,
  // is what makes the outer margin diff meaningfully instead of reporting
  // "100% different" on every pixel of it.
  const buf = await page.screenshot({ omitBackground: true });
  await context.close();

  return buf;
}

// Pads the smaller of two RGBA buffers (top-left anchored) so both share the
// same width/height. The two rasters only ever differ by a few px of
// rounding slop (see rasterizeSVG's cssWidth/cssHeight rounding) once the
// SVG has already been forced to the PNG's own target dimensions, so a
// transparent-black pad — rather than scaling either image again, or
// cropping content away — is the least lossy way to reconcile that residual
// slop before a pixel-for-pixel diff.
function padToCommonSize(a, b) {
  const width = Math.max(a.width, b.width);
  const height = Math.max(a.height, b.height);

  const pad = (img) => {
    if (img.width === width && img.height === height) {
      return img.data;
    }

    const buf = Buffer.alloc(width * height * 4, 0);

    for (let y = 0; y < img.height; y++) {
      img.data.copy(buf, y * width * 4, y * img.width * 4, (y * img.width + img.width) * 4);
    }

    return buf;
  };

  return { aData: pad(a), bData: pad(b), width, height };
}

async function processTheme(theme, ctx) {
  const configPath = path.join(THEMES_DIR, `${theme}.omp.json`);

  if (!fs.existsSync(configPath)) {
    throw new Error(`theme not found: ${configPath}`);
  }

  const pngPath = path.join(OUT_DIR, `${theme}.png`);
  const svgPath = path.join(OUT_DIR, `${theme}.svg`);
  const rasterPath = path.join(OUT_DIR, `${theme}.raster.png`);
  const diffPath = path.join(OUT_DIR, `${theme}.diff.png`);

  run(ctx.oldBin, [
    "config",
    "export",
    "image",
    "--config",
    configPath,
    "--data",
    DATA_FIXTURE,
    "--format",
    "png",
    "-o",
    pngPath,
  ]);

  run(ctx.newBin, [
    "config",
    "export",
    "image",
    "--config",
    configPath,
    "--data",
    DATA_FIXTURE,
    "--font-family",
    FONT_FAMILY,
    "-o",
    svgPath,
  ]);

  const { width: pngWidth, height: pngHeight } = readPngDimensions(pngPath);
  const svgMarkup = fs.readFileSync(svgPath, "utf8");

  const rasterBuf = await rasterizeSVG(ctx.browser, svgMarkup, ctx.fontBase64, pngWidth, pngHeight);
  fs.writeFileSync(rasterPath, rasterBuf);

  const png = PNG.sync.read(fs.readFileSync(pngPath));
  const raster = PNG.sync.read(rasterBuf);

  const dimensionsMatched = png.width === raster.width && png.height === raster.height;
  const { aData, bData, width, height } = padToCommonSize(png, raster);

  const diff = new PNG({ width, height });
  // includeAA: false marks antialiasing-only pixels (font hinting, shadow
  // falloff, the feDropShadow-vs-stackblur gap the task brief calls out as
  // expected and uninteresting) in the diff image without counting them —
  // this is the "structural" number, meant to track real content
  // differences (missing glyphs, wrong colors, misaligned icons) rather
  // than rasterizer noise. A second includeAA: true pass over the same
  // buffers (no image, just a count) reports how much of the raw pixel
  // difference that AA/blur noise actually was, for context.
  const structuralDiffPixels = pixelmatch(aData, bData, diff.data, width, height, {
    threshold: ctx.threshold,
    includeAA: false,
  });
  const rawDiffPixels = pixelmatch(aData, bData, null, width, height, {
    threshold: ctx.threshold,
    includeAA: true,
  });

  fs.writeFileSync(diffPath, PNG.sync.write(diff));

  const totalPixels = width * height;

  return {
    theme,
    pngDims: `${png.width}x${png.height}`,
    rasterDims: `${raster.width}x${raster.height}`,
    dimensionsMatched,
    structuralPct: (structuralDiffPixels / totalPixels) * 100,
    rawPct: (rawDiffPixels / totalPixels) * 100,
    files: {
      png: `${theme}.png`,
      raster: `${theme}.raster.png`,
      diff: `${theme}.diff.png`,
    },
  };
}

function writeIndexHtml(results) {
  const rows = results
    .map(
      (r) => `
    <section class="theme">
      <h2>${escapeHtml(r.theme)}</h2>
      <p class="stats">
        structural diff: <strong>${r.structuralPct.toFixed(2)}%</strong>
        &nbsp;·&nbsp; raw diff (incl. antialiasing): ${r.rawPct.toFixed(2)}%
        &nbsp;·&nbsp; PNG ${r.pngDims} vs raster ${r.rasterDims}${r.dimensionsMatched ? "" : " (padded to compare)"}
      </p>
      <div class="row">
        <figure>
          <figcaption>PNG (retired renderer)</figcaption>
          <div class="box"><img src="${r.files.png}" alt="${escapeHtml(r.theme)} PNG"></div>
        </figure>
        <figure>
          <figcaption>SVG raster (current renderer, Hack Nerd Font, ${DEVICE_SCALE_FACTOR}x)</figcaption>
          <div class="box"><img src="${r.files.raster}" alt="${escapeHtml(r.theme)} SVG raster"></div>
        </figure>
        <figure>
          <figcaption>diff (red = structural, yellow = antialiasing-only)</figcaption>
          <div class="box diffbox"><img src="${r.files.diff}" alt="${escapeHtml(r.theme)} diff"></div>
        </figure>
      </div>
    </section>`,
    )
    .join("\n");

  const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>SVG vs PNG acceptance harness</title>
<style>
  :root { color-scheme: dark; }
  body {
    background: #14161a;
    color: #e6e9ef;
    font: 14px/1.5 system-ui, sans-serif;
    padding: 24px;
    margin: 0;
  }
  h1 { font-size: 18px; margin: 0 0 6px; }
  p.intro { color: #8b98a9; margin: 0 0 28px; max-width: 72ch; }
  h2 { font-size: 16px; margin: 0 0 4px; color: #9fd0ff; }
  .stats { font-size: 12px; color: #8b98a9; margin: 0 0 10px; }
  .row { display: flex; gap: 14px; flex-wrap: wrap; align-items: flex-start; }
  figure { margin: 0; }
  figcaption {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: #8b98a9;
    margin: 0 0 4px;
  }
  .box {
    background: #0c0f14;
    border: 1px solid #232c39;
    border-radius: 6px;
    padding: 8px;
    overflow: auto;
    max-width: 640px;
    max-height: 260px;
  }
  .diffbox { background: #000; }
  img { display: block; width: auto; max-width: none; image-rendering: pixelated; }
  section.theme { margin-bottom: 40px; padding-bottom: 24px; border-bottom: 1px solid #232c39; }
</style>
</head>
<body>
  <h1>SVG exporter vs retired PNG renderer</h1>
  <p class="intro">
    Developer acceptance harness, not a CI gate. Each theme is exported from the retired PNG
    renderer and the current SVG renderer against the same deterministic --data fixture, both in
    Hack Nerd Font. The SVG is rasterized headlessly at ${DEVICE_SCALE_FACTOR}x scale (matching the
    PNG renderer's 48px reference em against the SVG's 16px default) before diffing with
    pixelmatch. Scroll each box independently; images are shown at native pixel size.
  </p>
  ${rows}
</body>
</html>`;

  fs.writeFileSync(path.join(OUT_DIR, "index.html"), html);
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const themes = resolveThemeList(opts);

  if (!fs.existsSync(DATA_FIXTURE)) {
    throw new Error(`data fixture not found: ${DATA_FIXTURE}`);
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });

  if (!opts.skipBuild) {
    buildBinaries(opts);
  } else if (!fs.existsSync(OLD_BIN) || !fs.existsSync(NEW_BIN)) {
    throw new Error("--skip-build was passed but bin/omp-png.exe / bin/omp-svg.exe are missing; run once without it first");
  }

  ensureFont();
  const fontBase64 = fs.readFileSync(FONT_PATH).toString("base64");

  console.log(`\nComparing ${themes.length} theme(s): ${themes.join(", ")}\n`);

  const browser = await chromium.launch();
  const ctx = { oldBin: OLD_BIN, newBin: NEW_BIN, browser, fontBase64, threshold: opts.threshold };

  const results = [];

  try {
    for (const theme of themes) {
      console.log(`\n=== ${theme} ===`);
      const result = await processTheme(theme, ctx);
      results.push(result);
      console.log(
        `  structural diff: ${result.structuralPct.toFixed(2)}%  raw diff: ${result.rawPct.toFixed(2)}%  ` +
          `(PNG ${result.pngDims} vs raster ${result.rasterDims})`,
      );
    }
  } finally {
    await browser.close();
  }

  writeIndexHtml(results);

  console.log("\n--- Summary ---");
  for (const r of results) {
    console.log(`${r.theme.padEnd(24)} structural ${r.structuralPct.toFixed(2).padStart(6)}%   raw ${r.rawPct.toFixed(2).padStart(6)}%`);
  }

  console.log(`\nContact sheet: ${path.join(OUT_DIR, "index.html")}`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});

