#!/usr/bin/env node
// Side-by-side renderer for eyeballing the SVG exporter against the retired
// PNG renderer. Unlike compare.mjs this does NOT force the SVG into the PNG's
// box (no preserveAspectRatio override, no rescale): each side is rasterized
// at its own natural geometry, so layout differences — whitespace collapse,
// baseline drift, misplaced decorations — stay visible instead of being
// squeezed away by the fit.
//
//   node shot.mjs glowsticks cobalt2
//   node shot.mjs --svg-only glowsticks
//
// Output lands in ./out/: <theme>.svg, <theme>.raster.png, and — unless
// --svg-only — <theme>.png from the retired renderer.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { chromium } from "playwright";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..", "..");
const THEMES_DIR = path.join(REPO_ROOT, "themes");
const DATA_FIXTURE = path.join(REPO_ROOT, "src", "prompt", "testdata", "fixtures", "prompt.data.json");

const BIN_DIR = path.join(__dirname, "bin");
const OUT_DIR = path.join(__dirname, "out");
const FONT_PATH = path.join(__dirname, "fonts", "HackNerdFont-Regular.ttf");
const FONT_FAMILY = "Hack Nerd Font";

const EXE = process.platform === "win32" ? ".exe" : "";
const OLD_BIN = path.join(BIN_DIR, `omp-png${EXE}`);
const NEW_BIN = path.join(BIN_DIR, `omp-svg${EXE}`);

// The exporter renders at a 16px em; the retired PNG renderer's reference em
// was 48px. Rasterizing at 3x device scale puts both at the same resolution
// without touching the SVG's own geometry.
const DEVICE_SCALE_FACTOR = 3;

function themeConfig(theme) {
  for (const ext of [".omp.yaml", ".omp.json", ".omp.toml", ".omp.jsonc"]) {
    const candidate = path.join(THEMES_DIR, theme + ext);

    if (fs.existsSync(candidate)) {
      return candidate;
    }
  }

  throw new Error(`theme not found: ${theme}`);
}

function run(cmd, args, cwd) {
  const res = spawnSync(cmd, args, { cwd, stdio: "inherit", shell: false });

  if (res.error) {
    throw res.error;
  }

  if (res.status !== 0) {
    throw new Error(`command failed (exit ${res.status}): ${cmd} ${args.join(" ")}`);
  }
}

// Reads width/height off the root <svg> element so the page can give it a box
// of exactly that size — the SVG then renders 1:1 with no scaling at all.
function svgSize(markup) {
  const width = /<svg[^>]*\swidth="([\d.]+)"/.exec(markup);
  const height = /<svg[^>]*\sheight="([\d.]+)"/.exec(markup);

  if (!width || !height) {
    throw new Error("could not read width/height off the root <svg>");
  }

  return { width: Number.parseFloat(width[1]), height: Number.parseFloat(height[1]) };
}

async function rasterize(browser, markup, fontBase64) {
  const { width, height } = svgSize(markup);

  const context = await browser.newContext({
    viewport: { width: Math.ceil(width), height: Math.ceil(height) },
    deviceScaleFactor: DEVICE_SCALE_FACTOR,
  });

  const page = await context.newPage();

  const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  @font-face {
    font-family: "${FONT_FAMILY}";
    src: url(data:font/ttf;base64,${fontBase64}) format("truetype");
    font-weight: normal;
    font-style: normal;
  }
  html, body { margin: 0; padding: 0; background: transparent; }
  svg { display: block; }
</style>
</head>
<body>${markup}</body>
</html>`;

  await page.setContent(html, { waitUntil: "networkidle" });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(50);

  const buf = await page.screenshot({ omitBackground: true });
  await context.close();

  return buf;
}

async function main() {
  const args = process.argv.slice(2);
  const svgOnly = args.includes("--svg-only");
  const themes = args.filter((a) => !a.startsWith("--"));

  if (themes.length === 0) {
    throw new Error("pass at least one theme name");
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });

  run("go", ["build", "-o", NEW_BIN, "."], path.join(REPO_ROOT, "src"));

  const fontBase64 = fs.readFileSync(FONT_PATH).toString("base64");
  const browser = await chromium.launch();

  try {
    for (const theme of themes) {
      const config = themeConfig(theme);
      const svgPath = path.join(OUT_DIR, `${theme}.svg`);

      run(NEW_BIN, [
        "config", "export", "image",
        "--config", config,
        "--data", DATA_FIXTURE,
        "--font-family", FONT_FAMILY,
        "-o", svgPath,
      ]);

      const markup = fs.readFileSync(svgPath, "utf8");
      fs.writeFileSync(path.join(OUT_DIR, `${theme}.raster.png`), await rasterize(browser, markup, fontBase64));

      if (!svgOnly && fs.existsSync(OLD_BIN)) {
        run(OLD_BIN, [
          "config", "export", "image",
          "--config", config,
          "--data", DATA_FIXTURE,
          "--format", "png",
          "-o", path.join(OUT_DIR, `${theme}.png`),
        ]);
      }

      console.log(`${theme}: ${svgPath}`);
    }
  } finally {
    await browser.close();
  }
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});

