// Probe: which whitespace declaration actually makes a headless Chromium keep
// the leading/trailing spaces inside an SVG <text>? The exporter writes
// white-space="pre" on the root <svg>; this measures whether that survives.
import { chromium } from "playwright";

const TEXT = "  ab  "; // 6 cells; collapses to "ab" (2) if whitespace is processed

const CASES = {
  'root white-space="pre"': `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="40" font-family="monospace" font-size="16px" white-space="pre"><text id="t" x="0" y="20">${TEXT}</text></svg>`,
  'root xml:space="preserve"': `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="40" font-family="monospace" font-size="16px" xml:space="preserve"><text id="t" x="0" y="20">${TEXT}</text></svg>`,
  'text xml:space="preserve"': `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="40" font-family="monospace" font-size="16px"><text id="t" x="0" y="20" xml:space="preserve">${TEXT}</text></svg>`,
  'root style="white-space:pre"': `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="40" font-family="monospace" font-size="16px" style="white-space:pre"><text id="t" x="0" y="20">${TEXT}</text></svg>`,
  "no declaration (baseline)": `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="40" font-family="monospace" font-size="16px"><text id="t" x="0" y="20">${TEXT}</text></svg>`,
};

const browser = await chromium.launch();
const page = await browser.newPage();

// Reference width of the same string with every space forced to a visible
// glyph, so "preserved" vs "collapsed" is a ratio, not an absolute px guess.
await page.setContent(
  `<!doctype html><body><svg xmlns="http://www.w3.org/2000/svg" font-family="monospace" font-size="16px"><text id="t" x="0" y="20">__ab__</text><text id="u" x="0" y="20">ab</text></svg>`,
);

const { six, two } = await page.evaluate(() => ({
  six: document.getElementById("t").getComputedTextLength(),
  two: document.getElementById("u").getComputedTextLength(),
}));

console.log(`reference: 6 cells = ${six.toFixed(2)}px, 2 cells = ${two.toFixed(2)}px\n`);

for (const [label, markup] of Object.entries(CASES)) {
  await page.setContent(`<!doctype html><body>${markup}`);

  const width = await page.evaluate(() => document.getElementById("t").getComputedTextLength());
  const cells = width / (six / 6);

  console.log(`${label.padEnd(30)} ${width.toFixed(2)}px  ≈ ${cells.toFixed(2)} cells  ${cells > 4 ? "PRESERVED" : "COLLAPSED"}`);
}

await browser.close();

