package cli

import (
	"os"
	"path/filepath"
	"strings"

	"github.com/jandedobbeleer/oh-my-posh/src/color"
	"github.com/jandedobbeleer/oh-my-posh/src/config"
	"github.com/jandedobbeleer/oh-my-posh/src/prompt"
	"github.com/jandedobbeleer/oh-my-posh/src/regex"
	"github.com/jandedobbeleer/oh-my-posh/src/svg"
	"github.com/jandedobbeleer/oh-my-posh/src/terminal"
)

// svgFontSize mirrors svg.Options.FontSize's own default (svg.go's
// defaultFontSize, unexported): the image command has no --font-size flag
// of its own, so this is the effective FontSize --cell-width/--line-height's
// ratio inputs get resolved against (see svgOptions).
const svgFontSize = 16.0

// exportSVG renders eng's already-captured Run stream (terminal.CaptureRuns
// must have been true for the eng.Primary() call that preceded this) to a
// non-rasterized SVG file. columns is the --terminal-width the prompt was
// rendered with (see svgOptions). cellWidth/lineHeight are the --cell-width/
// --line-height flags' raw values (see svgOptions).
func exportSVG(eng *prompt.Engine, cfg *config.Config, output, fontFamily string, columns int, cellWidth, lineHeight float64) error {
	rows := eng.CapturedRuns()

	doc, err := svg.Encode(rows, svgOptions(fontFamily, columns, cellWidth, lineHeight))
	if err != nil {
		return err
	}

	path := svgOutputPath(cfg.Source, output)

	return os.WriteFile(path, []byte(doc), 0o644) //nolint:gosec
}

// svgOptions resolves the two colors a Run stream can't carry itself — the
// real terminal background and the resolved accent — from the same
// terminal.Colors/terminal.BackgroundColor the ANSI writer already uses, so
// the SVG's "default"/"accent" colors match what a real terminal would show.
// fontFamily is the --font-family flag's raw value; an empty string leaves
// svg.Options.FontFamily unset, so Encode falls back to its own default
// Nerd Font stack. columns is the --terminal-width flag's value: the prompt
// engine already renders at this width (see runtime.Flags.TerminalWidth in
// the image command's Run func), so the exported canvas must use the same
// value, or right-aligned blocks/rprompts computed for that width would land
// in a canvas shrink-wrapped (or fixed) to a different one.
//
// cellWidth/lineHeight are the --cell-width/--line-height flags' raw values,
// expressed as a multiple of font-size (e.g. 0.6021, not a pixel count) —
// the same units the font-metric measurements behind svg.Options'
// CellWidth/LineHeight defaults are quoted in, and the natural unit for a
// caller quoting a font's own advance/line-height ratio. svg.Options'
// fields themselves are absolute (the same unit FontSize is in, not a
// ratio of it — see their own doc comments), so a nonzero flag value is
// scaled by svgFontSize here before being stored. Zero leaves the
// corresponding svg.Options field unset, so Encode falls back to its own
// Hack-derived default, correct for the bundled font stack but not for a
// caller (e.g. the website, rendering in Victor Mono) using a different
// font.
func svgOptions(fontFamily string, columns int, cellWidth, lineHeight float64) svg.Options {
	var opts svg.Options

	opts.FontFamily = fontFamily
	opts.Columns = columns

	if cellWidth != 0 {
		opts.CellWidth = cellWidth * svgFontSize
	}

	if lineHeight != 0 {
		opts.LineHeight = lineHeight * svgFontSize
	}

	if accentFg, ok := svg.ParseTrueColorSGR(terminal.Colors.ToAnsi(color.Accent, false)); ok {
		opts.AccentForeground = accentFg
	}

	if accentBg, ok := svg.ParseTrueColorSGR(terminal.Colors.ToAnsi(color.Accent, true)); ok {
		opts.AccentBackground = accentBg
	}

	if bg, ok := svg.ResolveStaticRGB(terminal.BackgroundColor, true, &opts); ok {
		opts.TerminalBackground = bg
	}

	return opts
}

// svgOutputPath derives the export path: an explicit --output wins (with its
// extension swapped to .svg, so -o mytheme.png still produces mytheme.svg),
// otherwise the config's own basename does, falling back to "prompt.svg"
// when neither yields a usable name.
func svgOutputPath(configPath, output string) string {
	const svgExt = ".svg"

	if output != "" {
		path := cleanOutputPath(output)
		return strings.TrimSuffix(path, filepath.Ext(path)) + svgExt
	}

	base := filepath.Base(configPath)

	match := regex.FindNamedRegexMatch(`(\.?)(?P<STR>.*)\.(json|yaml|yml|toml|jsonc)`, base)
	name := strings.TrimRight(match["STR"], ".omp")

	if name == "" {
		name = "prompt"
	}

	return name + svgExt
}

