"""Print a TTF's name-table entries (family, subfamily, full name, version)."""
import struct
import sys

IDS = {1: "family", 2: "subfamily", 4: "full name", 5: "version", 6: "postscript"}


def tables(data):
    n = struct.unpack(">H", data[4:6])[0]
    out = {}
    for i in range(n):
        off = 12 + i * 16
        tag = data[off:off + 4].decode("latin-1")
        to, tl = struct.unpack(">II", data[off + 8:off + 16])
        out[tag] = (to, tl)
    return out


for path in sys.argv[1:]:
    data = open(path, "rb").read()
    base = tables(data)["name"][0]
    count, string_off = struct.unpack(">HH", data[base + 2:base + 6])
    seen = {}

    for i in range(count):
        rec = base + 6 + i * 12
        pid, eid, lid, nid, length, off = struct.unpack(">HHHHHH", data[rec:rec + 12])

        if nid not in IDS or nid in seen:
            continue

        raw = data[base + string_off + off:base + string_off + off + length]
        seen[nid] = raw.decode("utf-16-be" if pid == 3 else "latin-1", "replace")

    print(path.replace("\\", "/").split("/")[-1])
    for nid in sorted(seen):
        print(f"  {IDS[nid]:12} {seen[nid]}")
    print()

