2	// Side-by-side renderer for eyeballing the SVG exporter against the retired
3	// PNG renderer. Unlike compare.mjs this does NOT force the SVG into the PNG's
4	// box (no preserveAspectRatio override, no rescale): each side is rasterized
5	// at its own natural geometry, so layout differences — whitespace collapse,
6	// baseline drift, misplaced decorations — stay visible instead of being
7	// squeezed away by the fit.
8	//
9	//   node shot.mjs glowsticks cobalt2
10	//   node shot.mjs --svg-only glowsticks
11	//   node shot.mjs --website glowsticks      as the theme gallery renders it
12	//
13	// Output lands in ./out/: <theme>.svg, <theme>.raster.png, and — unless
14	// --svg-only — <theme>.png from the retired renderer.
15	import fs from "node:fs";
16	import path from "node:path";
17	import { fileURLToPath } from "node:url";
18	
