35	// The Mono patched variant, which is what the exporter's default font stack
36	// asks for first and what a terminal actually runs: it scales Nerd Font icon
37	// ink down to one cell, where the plain variant lets it bleed up to ~1.9
38	// cells over the next character. The retired PNG renderer loaded the plain
39	// variant and compensated with a hand-maintained double-width table, so its
40	// reference renders show icons in a two-cell box; that is the one place the
41	// two renderers are expected to differ.
42	const FONT_PATH = path.join(__dirname, "fonts", "HackNerdFontMono-Regular.ttf");
43	const FONT_FAMILY = "Hack Nerd Font Mono";
