45	// --website renders exactly what the theme gallery ships: the font the site
46	// serves, at the metrics website/export_themes.mjs passes. Those metrics are
47	// Victor Mono's own (cell 600/1100 em, hhea line height 1.4091 em x 1.2), not
48	// the exporter's Hack-derived defaults, so they have to be passed here too or
49	// the grid would be laid out for the wrong font. Sourced from
50	// website/export_themes.mjs's VICTOR_MONO rather than re-derived or
51	// paraphrased here - that file is the single source of truth for these
52	// numbers, derivation comments included.
53	const WEBSITE = {
54	  // The gallery's own hand-written segment data, not the hermetic test
55	  // fixture: it is what decides which segments are enabled, so rendering a
56	  // theme against the fixture instead can leave out the very segment being
57	  // looked at.
58	  data: path.join(REPO_ROOT, "website", "segment_data.json"),
59	  fontPath: path.join(REPO_ROOT, "website", "static", "fonts", "VictorMono.ttf"),
60	  fontFamily: VICTOR_MONO.FONT_FAMILY,
