64	  fillDescent: String(VICTOR_MONO.FILL_DESCENT),
65	};
66	
67	function themeConfig(theme) {
68	  for (const ext of [".omp.yaml", ".omp.json", ".omp.toml", ".omp.jsonc"]) {
69	    const candidate = path.join(THEMES_DIR, theme + ext);
70	
71	    if (fs.existsSync(candidate)) {
72	      return candidate;
73	    }
74	  }
75	
76	  throw new Error(`theme not found: ${theme}`);
77	}
78	
79	// Reads width/height off the root <svg> element so the page can give it a box
80	// of exactly that size — the SVG then renders 1:1 with no scaling at all.
81	function svgSize(markup) {
82	  const width = /<svg[^>]*\swidth="([\d.]+)"/.exec(markup);
83	  const height = /<svg[^>]*\sheight="([\d.]+)"/.exec(markup);
84	
85	  if (!width || !height) {
86	    throw new Error("could not read width/height off the root <svg>");
87	  }
88	
89	  return { width: Number.parseFloat(width[1]), height: Number.parseFloat(height[1]) };
90	}
91	
92	async function rasterize(browser, markup, fontBase64, fontFamily) {
93	  const { width, height } = svgSize(markup);
94	
95	  const context = await browser.newContext({
96	    viewport: { width: Math.ceil(width), height: Math.ceil(height) },
97	    deviceScaleFactor: DEVICE_SCALE_FACTOR,
98	  });
99	
100	  const page = await context.newPage();
101	
102	  const html = `<!doctype html>
103	<html>
104	<head>
105	<meta charset="utf-8">
106	<style>
107	  @font-face {
108	    font-family: "${fontFamily}";
109	    src: url(data:font/ttf;base64,${fontBase64}) format("truetype");
110	    font-weight: normal;
111	    font-style: normal;
112	  }
113	  html, body { margin: 0; padding: 0; background: transparent; }
114	  svg { display: block; }
115	</style>
116	</head>
117	<body>${markup}</body>
118	</html>`;
119	
120	  await page.setContent(html, { waitUntil: "networkidle" });
121	  await page.evaluate(() => document.fonts.ready);
122	  await page.waitForTimeout(50);
123	
124	  const buf = await page.screenshot({ omitBackground: true });
125	  await context.close();
126	
127	  return buf;
128	}
129	
130	async function main() {
131	  const args = process.argv.slice(2);
132	  const svgOnly = args.includes("--svg-only");
133	  const website = args.includes("--website");
134	  const themes = args.filter((a) => !a.startsWith("--"));
135	
136	  if (themes.length === 0) {
137	    throw new Error("pass at least one theme name");
138	  }
139	
140	  fs.mkdirSync(OUT_DIR, { recursive: true });
141	
142	  run("go", ["build", "-o", NEW_BIN, "."], path.join(REPO_ROOT, "src"));
143	
144	  const fontFamily = website ? WEBSITE.fontFamily : FONT_FAMILY;
145	  const fontPath = website ? WEBSITE.fontPath : FONT_PATH;
146	
147	  if (!website) {
148	    await ensureFont("HackNerdFontMono-Regular.ttf", FONT_PATH);
149	  }
150	
151	  const fontBase64 = fs.readFileSync(fontPath).toString("base64");
152	  const browser = await chromium.launch();
153	
154	  try {
155	    for (const theme of themes) {
156	      const config = themeConfig(theme);
157	      const svgPath = path.join(OUT_DIR, `${theme}.svg`);
158	
159	      run(NEW_BIN, [
160	        "config", "export", "image",
161	        "--config", config,
162	        "--data", website ? WEBSITE.data : DATA_FIXTURE,
163	        "--font-family", fontFamily,
164	        ...(website
165	          ? [
166	              "--cell-width", WEBSITE.cellWidth,
167	              "--line-height", WEBSITE.lineHeight,
168	              "--fill-ascent", WEBSITE.fillAscent,
169	              "--fill-descent", WEBSITE.fillDescent,
170	            ]
171	          : []),
172	        "-o", svgPath,
173	      ]);
174	
175	      const markup = fs.readFileSync(svgPath, "utf8");
176	      fs.writeFileSync(path.join(OUT_DIR, `${theme}.raster.png`), await rasterize(browser, markup, fontBase64, fontFamily));
177	
178	      if (!svgOnly && fs.existsSync(OLD_BIN)) {
179	        run(OLD_BIN, [
180	          "config", "export", "image",
181	          "--config", config,
182	          "--data", DATA_FIXTURE,
183	          "--format", "png",
184	          "-o", path.join(OUT_DIR, `${theme}.png`),
185	        ]);
186	      }
187	
188	      console.log(`${theme}: ${svgPath}`);
189	    }
190	  } finally {
191	    await browser.close();
192	  }
193	}
194	
195	main().catch((err) => {
196	  console.error(err);
197	  process.exitCode = 1;
198	});

