39	  CELL_WIDTH: 0.5455,
40	  LINE_HEIGHT: 1.6909,
41	  // The box Victor Mono's powerline separators actually ink, read from the
42	  // glyf entry for U+E0B0 (and shared verbatim by U+E0B2/E0B4/E0B6/E0B8):
43	  // y -358..1208 at unitsPerEm 1100, so 1208/1100 = 1.0982em above the
44	  // baseline and 358/1100 = 0.3255em below it. A segment's background is
45	  // drawn to this box rather than to LineHeight, which is 19% taller - see
46	  // svg.Options' FillAscent/FillDescent.
47	  FILL_ASCENT: 1.0982,
