1	package prompt
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/jandedobbeleer/oh-my-posh/src/cache"
8		"github.com/jandedobbeleer/oh-my-posh/src/config"
9		"github.com/jandedobbeleer/oh-my-posh/src/shell"
10		"github.com/jandedobbeleer/oh-my-posh/src/terminal"
11	)
12	
13	func (e *Engine) Primary() string {
14		return e.primaryInternal(false)
15	}
16	
17	func (e *Engine) primaryInternal(fromCache bool) string {
18		needsPrimaryRightPrompt := e.needsPrimaryRightPrompt()
19	
20		e.writePrimaryPromptInternal(needsPrimaryRightPrompt, fromCache)
21	
22		switch e.Env.Shell() {
23		case shell.ZSH:
24			if !e.Env.Flags().Eval {
25				break
26			}
27	
28			// Warp doesn't support RPROMPT so we need to write it manually
29			if e.isWarp() {
30				e.writePrimaryRightPrompt()
31				prompt := fmt.Sprintf("PS1=%s", shell.QuotePosixStr(e.string()))
32				return prompt
33			}
34	
35			prompt := fmt.Sprintf("PS1=%s", shell.QuotePosixStr(e.string()))
36			prompt += fmt.Sprintf("\nRPROMPT=%s", shell.QuotePosixStr(e.rprompt))
37	
38			return prompt
39		default:
40			if !needsPrimaryRightPrompt {
41				break
42			}
43	
44			e.writePrimaryRightPrompt()
45		}
46	
47		return e.string()
48	}
49	
50	func (e *Engine) writePrimaryPrompt(needsPrimaryRPrompt bool) {
51		e.writePrimaryPromptInternal(needsPrimaryRPrompt, false)
52	}
53	
54	func (e *Engine) writePrimaryPromptInternal(needsPrimaryRPrompt, fromCache bool) {
55		if e.Config.ShellIntegration {
56			exitCode, _ := e.Env.StatusCodes()
57			e.write(terminal.CommandFinished(exitCode, e.Env.Flags().NoExitCode))
58			e.write(terminal.PromptStart())
59		}
60	
61		// cache a pointer to the color cycle
62		cycle = &e.Config.Cycle
63		var cancelNewline, didRender bool
64	
65		// Choose block source based on whether we're rendering from cache
66		blocks := e.Config.Blocks
67		if fromCache {
68			blocks = e.allBlocks
69		}
70	
71		// Launch execution for every segment of every block up front so they all
72		// run concurrently; blocks are still rendered sequentially afterward, in
73		// order, so wall-clock latency becomes max(slowest segment) instead of
74		// sum(slowest segment per block). The cache path re-renders segment data
75		// that was already executed, so there's nothing to launch there.
76		var launched []chan result
77		if !fromCache {
78			launched = make([]chan result, len(blocks))
79			for i, block := range blocks {
80				if block.Type == config.RPrompt && !needsPrimaryRPrompt {
81					continue
82				}
83	
84				launched[i] = e.launchBlockSegments(block)
85			}
86		}
87	
88		// Drain every block's channel before rendering any block so that executed
89		// is fully populated up front. This allows cross-block .Segments.X
90		// dependencies to resolve in both directions — an earlier block can
91		// reference a segment from a later block and vice versa.
92		executed := make(map[string]bool)
93		allResults := make([][]*config.Segment, len(blocks))
94	
95		if !fromCache {
96			for i, block := range blocks {
97				if launched[i] == nil {
98					continue
99				}
100	
101				allResults[i] = drainBlockResults(launched[i], len(block.Segments), executed)
102			}
103		}
104	
105		for i, block := range blocks {
106			// do not print a leading newline when we're at the first row and the prompt is cleared
107			if i == 0 {
108				cancelNewline = e.cancelNewline()
109			}
110	
111			// skip setting a newline when we didn't print anything yet
112			if i != 0 {
113				cancelNewline = !didRender
114			}
115	
116			if block.Type == config.RPrompt && !needsPrimaryRPrompt {
117				continue
118			}
119	
120			// Choose render method based on whether we're rendering from cache
121			var rendered bool
122			if fromCache {
123				rendered = e.renderBlockFromCache(block, cancelNewline)
124			} else {
125				rendered = e.renderLaunchedBlock(block, allResults[i], executed, cancelNewline)
126			}
127	
128			if rendered {
129				didRender = true
130			}
131		}
132	
133		// Only handle tooltip caching in regular (non-cached) rendering, once per
