func init() {
	const usage = "derive live state for a recorded --data file too, instead of replaying it hermetically (debugging)"

	printCmd.Flags().BoolVar(&dataDerive, "data-derive", false, usage)
	imageCmd.Flags().BoolVar(&dataDerive, "data-derive", false, usage)
