// A browser has no battery interface this package can reach - navigator.getBattery
// is a JavaScript API, not a syscall, and it is deprecated and gated behind
// permissions besides. The wasm build exists to render a prompt from recorded data
// (see runtime.Flags.DataOnly), where no segment probes the machine at all, so
// returning an error here is the honest answer rather than a reason to bridge into
// JS. A battery segment rendered from a data file never calls this.
func Get() (*Info, error) {
	return nil, errors.New("battery information is not available in a browser")
}

