// Independent parity driver: instantiate the wasm module, render a theme, print
// the SVG to stdout. Deliberately gives the module a filesystem that refuses
// every call, so any segment that reaches for the disk fails loudly here rather
// than quietly succeeding — a real browser has no fs at all.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const [wasmPath, themePath, dataPath] = process.argv.slice(2);

const goroot = execFileSync("go", ["env", "GOROOT"], { encoding: "utf8" }).trim();
const shim = path.join(goroot, "lib", "wasm", "wasm_exec.js");

// The module reads config and data as strings we pass in; it must never need
// the host filesystem. Stub it to throw so a stray read cannot silently work.
const deny = () => {
  throw new Error("filesystem access denied: a browser has none");
};

globalThis.fs = new Proxy(
  { constants: { O_WRONLY: 1, O_RDWR: 2, O_CREAT: 64, O_TRUNC: 512, O_APPEND: 1024, O_EXCL: 128 } },
  {
    get(target, prop) {
      if (prop in target) {
        return target[prop];
      }
      // write is used by println/stderr; let it through to keep panics visible.
      if (prop === "write" || prop === "writeSync") {
        return (fd, buf, off, len, pos, cb) => {
          const slice = buf.subarray(off ?? 0, (off ?? 0) + (len ?? buf.length));
          process.stderr.write(slice);
          if (cb) cb(null, len ?? buf.length);
          return len ?? buf.length;
        };
      }
      return deny;
    },
  },
);

globalThis.process = process;
globalThis.performance ??= (await import("node:perf_hooks")).performance;
globalThis.crypto ??= (await import("node:crypto")).webcrypto;

await import(shim);

const go = new globalThis.Go();
const { instance } = await WebAssembly.instantiate(fs.readFileSync(wasmPath), go.importObject);

go.run(instance); // resolves when the module exits; ours blocks on a channel

const configText = fs.readFileSync(themePath, "utf8");
const format = path.extname(themePath).replace(".", "");
const dataJSON = fs.readFileSync(dataPath, "utf8");

const out = globalThis.render(configText, format, dataJSON, { columns: 120 });

if (out.error) {
  console.error("render error:", out.error);
  process.exit(1);
}

process.stdout.write(out.svg);
process.exit(0);

