// Render every bundled theme through the wasm module in one instance, writing
// each result to outDir. One instance is deliberate: it also exercises the
// entrypoint's per-call template-cache reset, which a fresh process per theme
// would hide.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";

const [wasmPath, themesDir, dataPath, outDir] = process.argv.slice(2);

const goroot = execFileSync("go", ["env", "GOROOT"], { encoding: "utf8" }).trim();
const shim = path.join(goroot, "lib", "wasm", "wasm_exec.js");

const deny = () => {
  throw new Error("filesystem access denied: a browser has none");
};

globalThis.fs = new Proxy(
  { constants: { O_WRONLY: 1, O_RDWR: 2, O_CREAT: 64, O_TRUNC: 512, O_APPEND: 1024, O_EXCL: 128 } },
  {
    get(target, prop) {
      if (prop in target) return target[prop];
      if (prop === "write" || prop === "writeSync") {
        return (fd, buf, off, len, pos, cb) => {
          process.stderr.write(buf.subarray(off ?? 0, (off ?? 0) + (len ?? buf.length)));
          if (cb) cb(null, len ?? buf.length);
          return len ?? buf.length;
        };
      }
      return deny;
    },
  },
);

globalThis.process = process;
globalThis.performance ??= (await import("node:perf_hooks")).performance;
globalThis.crypto ??= (await import("node:crypto")).webcrypto;

await import(pathToFileURL(shim).href);

const go = new globalThis.Go();
const { instance } = await WebAssembly.instantiate(fs.readFileSync(wasmPath), go.importObject);
go.run(instance);

const dataJSON = fs.readFileSync(dataPath, "utf8");
fs.mkdirSync(outDir, { recursive: true });

let ok = 0;
const failures = [];

for (const file of fs.readdirSync(themesDir).sort()) {
  const m = /^(.*)\.omp\.(json|yaml|toml)$/.exec(file);
  if (!m) continue;

  const [, name, format] = m;
  const out = globalThis.render(fs.readFileSync(path.join(themesDir, file), "utf8"), format, dataJSON, { columns: 120 });

  if (out.error) {
    failures.push(`${name}: ${out.error}`);
    continue;
  }

  fs.writeFileSync(path.join(outDir, `${name}.svg`), out.svg);
  ok++;
}

console.log(`rendered ${ok}, failed ${failures.length}`);
for (const f of failures) console.log("  " + f);
process.exit(failures.length ? 1 : 0);

