file.content:
.studio {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-top: 1.5rem;
}

.pane {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  min-width: 0;
}

.paneLabel {
  font-family: var(--ifm-font-family-monospace);
  font-size: 0.62rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--ifm-color-emphasis-600);
}

.editor {
  flex: 1;
  min-height: 22rem;
  box-sizing: border-box;
  padding: 0.75rem;
  font-family: var(--ifm-font-family-monospace);
  font-size: 0.8rem;
  line-height: 1.5;
  resize: vertical;
  border: 1px solid var(--omp-card-border-color);
  border-radius: var(--omp-card-radius);
  background: var(--omp-card-background);
  color: var(--ifm-font-color-base);
}

.editor:focus {
  outline: none;
  border-color: var(--ifm-color-primary);
}

.preview {
  flex: 1;
  min-height: 22rem;
  box-sizing: border-box;
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.6rem;
  overflow: auto;
  border: 1px solid var(--omp-card-border-color);
  border-radius: var(--omp-card-radius);
  background: var(--omp-card-background);
}

.svgWrapper {
  display: block;
  width: fit-content;
  max-width: 100%;
}

.svgWrapper :global(svg) {
  display: block;
  max-width: 100%;
  height: auto;
}

.wasmMessage,
.hint {
  margin: 0;
  font-size: 0.78rem;
  color: var(--ifm-color-emphasis-600);
}

.error {
  margin: 0;
  font-size: 0.78rem;
  font-family: var(--ifm-font-family-monospace);
  white-space: pre-wrap;
  color: var(--ifm-color-danger);
}

@media (max-width: 700px) {
  .studio {
    grid-template-columns: 1fr;
  }

  /* The preview's height on desktop matches the editor next to it; stacked on narrow
     viewports that just leaves empty space below a prompt SVG far shorter than 22rem. Let it
     shrink to fit its content instead. */
  .preview {
    min-height: 0;
  }
}

