import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import useIsBrowser from '@docusaurus/useIsBrowser';
import useBaseUrl from '@docusaurus/useBaseUrl';
import { VICTOR_MONO } from '../../../font-metrics.mjs';
import segmentData from '../../../segment_data.json';
import { CONFIG_FORMAT, STARTER_CONFIG } from './config';
import { loadWasmModule } from './wasmLoader';
import styles from './styles.module.css';

// Same synthetic data the theme gallery renders with (see website/export_themes.mjs and its own
// comment on segment_data.json) - passed as-is so the studio's preview matches the gallery
// instead of showing its own, differently-populated segments.
const DATA_JSON = JSON.stringify(segmentData);

// 120 columns matches the gallery (export_themes.mjs / plugins/themes); the four font metrics
// are Victor Mono's own, read once from font-metrics.mjs so this can never drift from what the
// gallery or tools/svg-png-compare/shot.mjs's --website mode pass.
const RENDER_OPTIONS = {
  columns: 120,
  fontFamily: VICTOR_MONO.FONT_FAMILY,
  cellWidth: VICTOR_MONO.CELL_WIDTH,
  lineHeight: VICTOR_MONO.LINE_HEIGHT,
  fillAscent: VICTOR_MONO.FILL_ASCENT,
  fillDescent: VICTOR_MONO.FILL_DESCENT,
};

// Rendering itself is local and fast (no network round trip), but re-running it on every
// keystroke would still mean parsing and re-executing every segment's templates on every single
// character typed. 200ms is long enough to coalesce a burst of keystrokes, short enough that the
// preview still feels live.
const DEBOUNCE_MS = 200;

function WasmMessage({ status, progress, errorMessage }) {
  if (status === 'ready') {
    return null;
  }

  if (status === 'error') {
    return (
      <p className={styles.wasmMessage}>
        Could not load the renderer: {errorMessage}
      </p>
    );
  }

  const pct = progress > 0 ? ` (${Math.round(progress * 100)}%)` : '';

  return (
    <p className={styles.wasmMessage}>
      Downloading the renderer{pct}. It is a ~29 MB WebAssembly build of oh-my-posh, fetched once
      per visit.
    </p>
  );
}

function Studio() {
  const isBrowser = useIsBrowser();
  const wasmExecUrl = useBaseUrl('/wasm_exec.js');
  const wasmUrl = useBaseUrl('/omp.wasm');

  const [configText, setConfigText] = useState(STARTER_CONFIG);
  const [svg, setSvg] = useState(null);
  const [error, setError] = useState(null);
  const [wasmStatus, setWasmStatus] = useState('loading');
  const [wasmProgress, setWasmProgress] = useState(0);
  const [wasmErrorMessage, setWasmErrorMessage] = useState('');

  // A ref, not state: the render function itself never needs to trigger a re-render when it
  // changes - only wasmStatus flipping to 'ready' does, and that already happens separately.
  const renderRef = useRef(null);
  const debounceRef = useRef(null);

  const runRender = useCallback((text) => {
    if (!renderRef.current) {
      return;
    }

    let result;

    try {
      result = renderRef.current(text, CONFIG_FORMAT, DATA_JSON, RENDER_OPTIONS);
    } catch (err) {
      // renderJS (src/wasm/main.go) is documented to always return {error} rather than throw,
      // but this is still untrusted-from-JS's-perspective wasm glue - fail closed rather than
      // let an unexpected exception escape.
      setError(err.message || String(err));
      return;
    }

    if (result && typeof result.error === 'string') {
      // Deliberately not touching `svg` here: an invalid half-typed config should leave the
      // last good preview on screen instead of blanking it (see the studio's own requirements).
      setError(result.error);
      return;
    }

    if (result && typeof result.svg === 'string') {
      setSvg(result.svg);
      setError(null);
      return;
    }

    setError('The renderer returned an unexpected response.');
  }, []);

  useEffect(() => {
    if (!isBrowser) {
      return undefined;
    }

    let cancelled = false;

    loadWasmModule(wasmExecUrl, wasmUrl, (fraction) => {
      if (!cancelled) {
        setWasmProgress(fraction);
      }
    })
      .then((renderFn) => {
        if (cancelled) {
          return;
        }

        renderRef.current = renderFn;
        setWasmStatus('ready');
      })
      .catch((err) => {
        if (cancelled) {
          return;
        }

        setWasmErrorMessage(err.message || String(err));
        setWasmStatus('error');
      });

    return () => {
      cancelled = true;
    };
  }, [isBrowser, wasmExecUrl, wasmUrl]);

  // Render the starter config as soon as the module is ready, so a prompt appears on first
  // paint without the user having to touch the editor.
  useEffect(() => {
    if (wasmStatus === 'ready') {
      runRender(configText);
    }
    // configText is intentionally not a dependency: this effect's only job is the one render
    // that happens the moment the module becomes ready, not every keystroke after - the
    // textarea's onChange handles that, debounced.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wasmStatus, runRender]);

  useEffect(
    () => () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    },
    [],
  );

  const handleChange = useCallback(
    (event) => {
      const value = event.target.value;
      setConfigText(value);

      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }

      debounceRef.current = setTimeout(() => runRender(value), DEBOUNCE_MS);
    },
    [runRender],
  );

  const previewHint = useMemo(() => {
    if (wasmStatus !== 'ready' || svg || error) {
      return null;
    }

    return 'Nothing to preview yet.';
  }, [wasmStatus, svg, error]);

  return (
    <div className={styles.studio}>
      <div className={styles.pane}>
        <span className={styles.paneLabel}>Config</span>
        <textarea
          className={styles.editor}
          value={configText}
          onChange={handleChange}
          spellCheck={false}
          autoComplete="off"
          autoCapitalize="off"
          rows={24}
          aria-label="Theme config"
        />
      </div>

      <div className={styles.pane}>
        <span className={styles.paneLabel}>Preview</span>
        <div className={styles.preview}>
          <WasmMessage status={wasmStatus} progress={wasmProgress} errorMessage={wasmErrorMessage} />

          {error && <p className={styles.error}>{error}</p>}

          {svg && (
            <span className={styles.svgWrapper} dangerouslySetInnerHTML={{ __html: svg }} />
          )}

          {previewHint && <p className={styles.hint}>{previewHint}</p>}
        </div>
      </div>
    </div>
  );
}

export default Studio;

