// The studio's starter config: small enough to read in one glance, but touches four different
// segments (git, node, python, battery) so the preview shows something meaningful on first paint
// without fetching a theme over the network. Kept in its own module rather than inline in
// index.js so the YAML itself is easy to scan without wading through component code.
//
// Every segment here has an entry in website/segment_data.json's "segments" map on purpose: the
// wasm module always renders with runtime.Flags.DataOnly set (see src/wasm/main.go's own doc
// comment on why), and under DataOnly a segment with no entry there is suppressed outright
// rather than rendered blank (src/config/segment.go's restoreData) - session/path/status, say,
// have no such entry and would silently vanish from the preview. Keep any future edit to this
// starter within segment types segment_data.json actually covers.
export const STARTER_CONFIG = `# yaml-language-server: $schema=https://raw.githubusercontent.com/JanDeDobbeleer/oh-my-posh/main/themes/schema.json
version: 4
final_space: true
blocks:
  - type: prompt
    alignment: left
    segments:
      - type: git
        style: plain
        foreground: p:yellow
        template: "{{ .HEAD }}{{ if .BranchStatus }} {{ .BranchStatus }}{{ end }} "

      - type: node
        style: plain
        foreground: p:green
        template: " node {{ .Full }} "

      - type: python
        style: plain
        foreground: p:blue
        template: " py {{ .Full }} "

      - type: battery
        style: plain
        foreground: p:red
        template: " {{ .Percentage }}% "
palette:
  blue: "#61AFEF"
  green: "#98C379"
  yellow: "#E5C07B"
  red: "#E06C75"
`;

// "yaml" here is the config's own format (config.ParseBytes's first argument), not a display
// language - it tells the parser how to read STARTER_CONFIG's text, the same way a theme file's
// extension does for the CLI. Fixed rather than user-selectable: the studio edits one config at
// a time, and switching formats would mean re-serializing the current text, which is out of
// scope here.
export const CONFIG_FORMAT = 'yaml';

