// language - it tells the parser how to read STARTER_CONFIG's text, the same way a theme file's
// extension does for the CLI. Fixed rather than user-selectable: the studio edits one config at
// a time, and switching formats would mean re-serializing the current text, which is out of
// scope here.
export const CONFIG_FORMAT = 'yaml';

