// Screenshot the pages under review plus a couple of reference pages that
// represent the site's settled look, so a reviewer can compare rather than
// judge in isolation.
import { chromium } from "playwright";

const base = process.argv[2];
const out = process.argv[3];

const PAGES = [
  ["studio", "/studio"],
  ["segments", "/segments"],
  ["home", "/"],
  ["docs", "/docs/installation/windows"],
  ["themes", "/docs/themes"],
];

const browser = await chromium.launch();

for (const [name, path] of PAGES) {
  for (const scheme of ["light", "dark"]) {
    const context = await browser.newContext({
      viewport: { width: 1440, height: 1200 },
      colorScheme: scheme,
    });
    const page = await context.newPage();

    await page.goto(base + path, { waitUntil: "networkidle" });
    // The studio only paints once its wasm module has loaded.
    await page.waitForTimeout(name === "studio" ? 20000 : 1200);

    await page.screenshot({ path: `${out}/${name}-${scheme}.png`, fullPage: false });
    console.log(name, scheme);

    await context.close();
  }
}

await browser.close();

