  color: var(--omp-text-secondary);
}

/* padding stays a literal 1rem: it sets the sidebar's own inner margin, not a gap between
   siblings, and 1rem sits exactly between --omp-space-2 (0.75rem) and --omp-space-3 (1.25rem) -
   forcing it either way would nudge the whole content column's inset. */
.content {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: var(--omp-space-2);
  min-width: 0;
